import * as React from 'react'
import { motion } from 'framer-motion'
import { Home, Settings, Bell, User, Menu, X, Search } from 'lucide-react'
import { cn } from '@/utils/cn'

// 顶部导航栏
interface HeaderProps {
  title: string
  user?: {
    name: string
    avatar?: string
    role?: string
  }
  onMenuClick?: () => void
  showSearch?: boolean
  onSearch?: (query: string) => void
  actions?: React.ReactNode
  className?: string
}

export const Header: React.FC<HeaderProps> = ({
  title,
  user,
  onMenuClick,
  showSearch = false,
  onSearch,
  actions,
  className
}) => {
  const [searchQuery, setSearchQuery] = React.useState('')
  const [showMobileSearch, setShowMobileSearch] = React.useState(false)

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault()
    onSearch?.(searchQuery)
  }

  return (
    <motion.header
      initial={{ y: -20, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      className={cn(
        'sticky top-0 z-40 w-full border-b border-gray-200/50 bg-white/80 backdrop-blur-xl',
        className
      )}
    >
      <div className="flex h-16 items-center justify-between px-4 md:px-6">
        {/* 左侧 */}
        <div className="flex items-center gap-4">
          {onMenuClick && (
            <button
              onClick={onMenuClick}
              className="p-2 rounded-lg hover:bg-gray-100 transition-colors lg:hidden"
            >
              <Menu className="h-5 w-5" />
            </button>
          )}
          <h1 className="text-xl font-semibold text-gray-900 hidden sm:block">
            {title}
          </h1>
        </div>

        {/* 中间搜索 */}
        {showSearch && !showMobileSearch && (
          <div className="hidden md:flex flex-1 max-w-md mx-8">
            <form onSubmit={handleSearch} className="w-full">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
                <input
                  type="text"
                  placeholder="搜索设备、告警..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full rounded-xl border border-gray-200/50 bg-white/80 backdrop-blur-lg pl-10 pr-4 py-2 text-sm transition-colors focus:border-purple-400 focus:bg-white focus:ring-2 focus:ring-purple-400/20 focus:outline-none"
                />
              </div>
            </form>
          </div>
        )}

        {/* 右侧 */}
        <div className="flex items-center gap-2">
          {/* 移动端搜索按钮 */}
          {showSearch && (
            <button
              onClick={() => setShowMobileSearch(!showMobileSearch)}
              className="p-2 rounded-lg hover:bg-gray-100 transition-colors md:hidden"
            >
              {showMobileSearch ? <X className="h-5 w-5" /> : <Search className="h-5 w-5" />}
            </button>
          )}

          {actions}

          {/* 通知 */}
          <button className="relative p-2 rounded-lg hover:bg-gray-100 transition-colors">
            <Bell className="h-5 w-5" />
            <span className="absolute -top-1 -right-1 h-4 w-4 rounded-full bg-red-500 text-xs text-white flex items-center justify-center">
              3
            </span>
          </button>

          {/* 用户菜单 */}
          {user && (
            <div className="flex items-center gap-3 pl-3 border-l border-gray-200">
              <div className="hidden sm:block text-right">
                <p className="text-sm font-medium text-gray-900">{user.name}</p>
                {user.role && (
                  <p className="text-xs text-gray-500">{user.role}</p>
                )}
              </div>
              <button className="w-8 h-8 rounded-full bg-purple-100 flex items-center justify-center overflow-hidden">
                {user.avatar ? (
                  <img
                    src={user.avatar}
                    alt={user.name}
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <User className="h-4 w-4 text-purple-600" />
                )}
              </button>
            </div>
          )}
        </div>
      </div>

      {/* 移动端搜索栏 */}
      {showSearch && showMobileSearch && (
        <motion.div
          initial={{ height: 0, opacity: 0 }}
          animate={{ height: 'auto', opacity: 1 }}
          exit={{ height: 0, opacity: 0 }}
          className="border-t border-gray-200/50 p-4 md:hidden"
        >
          <form onSubmit={handleSearch}>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
              <input
                type="text"
                placeholder="搜索设备、告警..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full rounded-xl border border-gray-200/50 bg-white/80 backdrop-blur-lg pl-10 pr-4 py-2 text-sm transition-colors focus:border-purple-400 focus:bg-white focus:ring-2 focus:ring-purple-400/20 focus:outline-none"
                autoFocus
              />
            </div>
          </form>
        </motion.div>
      )}
    </motion.header>
  )
}

// 侧边栏
interface SidebarItem {
  id: string
  label: string
  icon: React.ReactNode
  href: string
  badge?: number
  children?: Omit<SidebarItem, 'icon' | 'children'>[]
}

interface SidebarProps {
  items: SidebarItem[]
  activeItem?: string
  onItemClick?: (item: SidebarItem) => void
  collapsed?: boolean
  onCollapse?: (collapsed: boolean) => void
  className?: string
}

export const Sidebar: React.FC<SidebarProps> = ({
  items,
  activeItem,
  onItemClick,
  collapsed = false,
  onCollapse,
  className
}) => {
  const [expandedItems, setExpandedItems] = React.useState<Set<string>>(new Set())

  const toggleExpanded = (itemId: string) => {
    const newExpanded = new Set(expandedItems)
    if (newExpanded.has(itemId)) {
      newExpanded.delete(itemId)
    } else {
      newExpanded.add(itemId)
    }
    setExpandedItems(newExpanded)
  }

  const renderItem = (item: SidebarItem, level = 0) => {
    const isActive = activeItem === item.id
    const isExpanded = expandedItems.has(item.id)
    const hasChildren = item.children && item.children.length > 0

    return (
      <div key={item.id}>
        <button
          onClick={() => {
            if (hasChildren) {
              toggleExpanded(item.id)
            } else {
              onItemClick?.(item)
            }
          }}
          className={cn(
            'flex items-center w-full px-3 py-2.5 text-sm font-medium rounded-lg transition-all duration-200',
            level === 0 ? 'mx-2' : 'ml-6 mr-2',
            isActive
              ? 'bg-purple-100 text-purple-900'
              : 'text-gray-700 hover:bg-gray-100',
            collapsed && level === 0 && 'justify-center px-2'
          )}
        >
          <span className="flex-shrink-0">{item.icon}</span>
          {!collapsed && (
            <>
              <span className="ml-3 flex-1 text-left">{item.label}</span>
              {item.badge && item.badge > 0 && (
                <span className="ml-auto bg-red-100 text-red-600 text-xs px-2 py-0.5 rounded-full">
                  {item.badge}
                </span>
              )}
              {hasChildren && (
                <motion.div
                  animate={{ rotate: isExpanded ? 180 : 0 }}
                  transition={{ duration: 0.2 }}
                  className="ml-2"
                >
                  ↓
                </motion.div>
              )}
            </>
          )}
        </button>

        {/* 子项目 */}
        {hasChildren && !collapsed && (
          <motion.div
            initial={false}
            animate={{ height: isExpanded ? 'auto' : 0 }}
            transition={{ duration: 0.2 }}
            className="overflow-hidden"
          >
            {item.children!.map((child) => (
              <button
                key={child.id}
                onClick={() => onItemClick?.(child as SidebarItem)}
                className={cn(
                  'flex items-center w-full px-3 py-2 text-sm ml-8 mr-2 rounded-lg transition-colors',
                  activeItem === child.id
                    ? 'bg-purple-50 text-purple-700'
                    : 'text-gray-600 hover:bg-gray-50'
                )}
              >
                <span className="flex-1 text-left">{child.label}</span>
                {child.badge && child.badge > 0 && (
                  <span className="ml-auto bg-red-100 text-red-600 text-xs px-2 py-0.5 rounded-full">
                    {child.badge}
                  </span>
                )}
              </button>
            ))}
          </motion.div>
        )}
      </div>
    )
  }

  return (
    <motion.aside
      initial={false}
      animate={{ width: collapsed ? 64 : 256 }}
      transition={{ duration: 0.3, ease: 'easeInOut' }}
      className={cn(
        'flex flex-col h-full bg-white border-r border-gray-200/50',
        className
      )}
    >
      {/* 头部 */}
      <div className="flex items-center justify-between p-4 border-b border-gray-200/50">
        {!collapsed && (
          <h2 className="text-lg font-semibold text-gray-900">
            设备巡检系统
          </h2>
        )}
        {onCollapse && (
          <button
            onClick={() => onCollapse(!collapsed)}
            className="p-1.5 rounded-lg hover:bg-gray-100 transition-colors"
          >
            <motion.div
              animate={{ rotate: collapsed ? 180 : 0 }}
              transition={{ duration: 0.2 }}
            >
              ←
            </motion.div>
          </button>
        )}
      </div>

      {/* 导航项目 */}
      <nav className="flex-1 py-4 space-y-1 overflow-y-auto">
        {items.map((item) => renderItem(item))}
      </nav>

      {/* 底部 */}
      <div className="p-4 border-t border-gray-200/50">
        <button
          onClick={() => onItemClick?.({ id: 'settings', label: '设置', icon: <Settings className="h-5 w-5" />, href: '/settings' })}
          className={cn(
            'flex items-center w-full px-3 py-2.5 text-sm font-medium rounded-lg transition-colors text-gray-700 hover:bg-gray-100',
            collapsed && 'justify-center px-2'
          )}
        >
          <Settings className="h-5 w-5" />
          {!collapsed && <span className="ml-3">设置</span>}
        </button>
      </div>
    </motion.aside>
  )
}

'use client'

import React, { createContext, useContext, useCallback, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { CheckCircle, XCircle, AlertCircle, Info, Loader2, X } from 'lucide-react'

// 通知类型
export type NotificationType = 'success' | 'error' | 'warning' | 'info' | 'loading'

// 通知接口
export interface Notification {
  id: string
  type: NotificationType
  title: string
  message?: string
  duration?: number
  action?: {
    label: string
    onClick: () => void
  }
  persistent?: boolean
}

// 通知上下文
interface NotificationContextType {
  notifications: Notification[]
  addNotification: (notification: Omit<Notification, 'id'>) => string
  removeNotification: (id: string) => void
  clearAll: () => void

  // 便捷方法
  success: (title: string, message?: string, options?: Partial<Notification>) => string
  error: (title: string, message?: string, options?: Partial<Notification>) => string
  warning: (title: string, message?: string, options?: Partial<Notification>) => string
  info: (title: string, message?: string, options?: Partial<Notification>) => string
  loading: (title: string, message?: string, options?: Partial<Notification>) => string
}

const NotificationContext = createContext<NotificationContextType | null>(null)

// 生成唯一ID
const generateId = () => Math.random().toString(36).substr(2, 9)

// 通知Provider
export const NotificationProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [notifications, setNotifications] = useState<Notification[]>([])

  const addNotification = useCallback((notification: Omit<Notification, 'id'>) => {
    const id = generateId()
    const newNotification: Notification = {
      id,
      duration: 5000,
      ...notification
    }

    setNotifications(prev => [newNotification, ...prev])

    // 自动移除（除非是持久化通知或loading类型）
    if (!newNotification.persistent && newNotification.type !== 'loading' && newNotification.duration) {
      setTimeout(() => {
        removeNotification(id)
      }, newNotification.duration)
    }

    return id
  }, [])

  const removeNotification = useCallback((id: string) => {
    setNotifications(prev => prev.filter(notification => notification.id !== id))
  }, [])

  const clearAll = useCallback(() => {
    setNotifications([])
  }, [])

  // 便捷方法
  const success = useCallback((title: string, message?: string, options?: Partial<Notification>) => {
    return addNotification({ type: 'success', title, message, ...options })
  }, [addNotification])

  const error = useCallback((title: string, message?: string, options?: Partial<Notification>) => {
    return addNotification({ 
      type: 'error', 
      title, 
      message, 
      duration: 8000, 
      persistent: false,
      ...options 
    })
  }, [addNotification])

  const warning = useCallback((title: string, message?: string, options?: Partial<Notification>) => {
    return addNotification({ type: 'warning', title, message, ...options })
  }, [addNotification])

  const info = useCallback((title: string, message?: string, options?: Partial<Notification>) => {
    return addNotification({ type: 'info', title, message, ...options })
  }, [addNotification])

  const loading = useCallback((title: string, message?: string, options?: Partial<Notification>) => {
    return addNotification({ 
      type: 'loading', 
      title, 
      message, 
      persistent: true, 
      duration: undefined,
      ...options 
    })
  }, [addNotification])

  const value: NotificationContextType = {
    notifications,
    addNotification,
    removeNotification,
    clearAll,
    success,
    error,
    warning,
    info,
    loading
  }

  return (
    <NotificationContext.Provider value={value}>
      {children}
      <NotificationContainer />
    </NotificationContext.Provider>
  )
}

// 通知容器组件
const NotificationContainer: React.FC = () => {
  const context = useContext(NotificationContext)
  if (!context) return null

  const { notifications, removeNotification } = context

  return (
    <div className="fixed top-4 right-4 z-50 w-80 space-y-2">
      <AnimatePresence mode="popLayout">
        {notifications.map(notification => (
          <NotificationItem
            key={notification.id}
            notification={notification}
            onRemove={removeNotification}
          />
        ))}
      </AnimatePresence>
    </div>
  )
}

// 通知项组件
const NotificationItem: React.FC<{
  notification: Notification
  onRemove: (id: string) => void
}> = ({ notification, onRemove }) => {
  const getIcon = () => {
    switch (notification.type) {
      case 'success':
        return <CheckCircle className="w-5 h-5 text-green-500" data-testid="check-circle-icon" />
      case 'error':
        return <XCircle className="w-5 h-5 text-red-500" data-testid="x-circle-icon" />
      case 'warning':
        return <AlertCircle className="w-5 h-5 text-yellow-500" data-testid="alert-circle-icon" />
      case 'info':
        return <Info className="w-5 h-5 text-blue-500" data-testid="info-icon" />
      case 'loading':
        return <Loader2 className="w-5 h-5 text-blue-500 animate-spin" data-testid="loading-icon" />
      default:
        return <Info className="w-5 h-5 text-gray-500" data-testid="info-icon" />
    }
  }

  const getBgColor = () => {
    switch (notification.type) {
      case 'success':
        return 'bg-green-50 border-green-200'
      case 'error':
        return 'bg-red-50 border-red-200'
      case 'warning':
        return 'bg-yellow-50 border-yellow-200'
      case 'info':
        return 'bg-blue-50 border-blue-200'
      case 'loading':
        return 'bg-blue-50 border-blue-200'
      default:
        return 'bg-white border-gray-200'
    }
  }

  return (
    <motion.div
      layout
      initial={{ opacity: 0, y: -50, scale: 0.9 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={{ opacity: 0, x: 400, scale: 0.9 }}
      transition={{ duration: 0.3, ease: 'easeOut' }}
      className={`
        p-4 rounded-lg border shadow-lg backdrop-blur-sm
        ${getBgColor()}
      `}
    >
      <div className="flex items-start gap-3">
        <div className="flex-shrink-0 mt-0.5">
          {getIcon()}
        </div>

        <div className="flex-1 min-w-0">
          <div className="font-medium text-gray-900 mb-1">
            {notification.title}
          </div>
          {notification.message && (
            <div className="text-sm text-gray-600">
              {notification.message}
            </div>
          )}

          {notification.action && (
            <button
              onClick={notification.action.onClick}
              className="mt-2 text-sm font-medium text-blue-600 hover:text-blue-800"
            >
              {notification.action.label}
            </button>
          )}
        </div>

        <button
          onClick={() => onRemove(notification.id)}
          className="flex-shrink-0 text-gray-400 hover:text-gray-600 transition-colors"
          aria-label="Close notification"
        >
          <X className="w-4 h-4" />
        </button>
      </div>
    </motion.div>
  )
}

// Hook for using notifications
export const useNotifications = () => {
  const context = useContext(NotificationContext)
  if (!context) {
    throw new Error('useNotifications must be used within a NotificationProvider')
  }
  return context
}

// 操作反馈Hook
export const useOperationFeedback = () => {
  const notifications = useNotifications()

  const withFeedback = useCallback(async <T,>(
    operation: () => Promise<T>,
    options: {
      loadingMessage?: string
      successMessage?: string
      errorMessage?: string
      showSuccess?: boolean
    } = {}
  ): Promise<T> => {
    const {
      loadingMessage = '处理中...',
      successMessage = '操作成功',
      errorMessage = '操作失败',
      showSuccess = true
    } = options

    // 显示加载状态
    const loadingId = notifications.loading('处理中', loadingMessage)

    try {
      const result = await operation()

      // 移除加载提示
      notifications.removeNotification(loadingId)

      // 显示成功提示
      if (showSuccess) {
        notifications.success('操作成功', successMessage)
      }

      return result
    } catch (error) {
      // 移除加载提示
      notifications.removeNotification(loadingId)

      // 显示错误提示
      const errorMsg = error instanceof Error ? error.message : String(error)
      notifications.error('操作失败', errorMessage || errorMsg)

      throw error
    }
  }, [notifications])

  return { withFeedback }
}

// 确认对话框Hook
export const useConfirmDialog = () => {
  const [isOpen, setIsOpen] = useState(false)
  const [config, setConfig] = useState<{
    title: string
    message: string
    confirmText: string
    cancelText: string
    onConfirm: () => void | Promise<void>
    variant: 'default' | 'destructive'
  } | null>(null)

  const confirm = useCallback((options: {
    title: string
    message: string
    confirmText?: string
    cancelText?: string
    onConfirm: () => void | Promise<void>
    variant?: 'default' | 'destructive'
  }) => {
    return new Promise<boolean>((resolve) => {
      setConfig({
        confirmText: '确认',
        cancelText: '取消',
        variant: 'default',
        ...options,
        onConfirm: async () => {
          try {
            await options.onConfirm()
            resolve(true)
          } catch (error) {
            console.error('Confirm action failed:', error)
            resolve(false)
          }
          setIsOpen(false)
        }
      })
      setIsOpen(true)
    })
  }, [])

  const cancel = useCallback(() => {
    setIsOpen(false)
    setConfig(null)
  }, [])

  const ConfirmDialog = config ? (
    <motion.div
      className="fixed inset-0 z-50"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
    >
      {/* 背景遮罩 */}
      <div 
        className="absolute inset-0 bg-black/50"
        onClick={cancel}
      />

      {/* 对话框 */}
      <div className="relative z-10 flex items-center justify-center min-h-full p-4">
        <motion.div
          className="bg-white rounded-lg shadow-xl max-w-md w-full p-6"
          initial={{ scale: 0.9, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          exit={{ scale: 0.9, opacity: 0 }}
        >
          <h3 className="text-lg font-semibold text-gray-900 mb-4">
            {config.title}
          </h3>

          <p className="text-gray-600 mb-6">
            {config.message}
          </p>

          <div className="flex justify-end gap-3">
            <button
              onClick={cancel}
              className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors"
            >
              {config.cancelText}
            </button>

            <button
              onClick={config.onConfirm}
              className={`
                px-4 py-2 rounded-md font-medium transition-colors
                ${config.variant === 'destructive' 
                  ? 'bg-red-600 text-white hover:bg-red-700' 
                  : 'bg-blue-600 text-white hover:bg-blue-700'
                }
              `}
            >
              {config.confirmText}
            </button>
          </div>
        </motion.div>
      </div>
    </motion.div>
  ) : null

  return {
    isOpen,
    confirm,
    cancel,
    ConfirmDialog: isOpen ? ConfirmDialog : null
  }
}

'use client'

import React, { ReactNode, useEffect } from 'react'
import { usePathname } from 'next/navigation'
import { Sidebar } from '@/features/dashboard/components/Sidebar'
import { DashboardHeader } from '@/features/dashboard/components/DashboardHeader'
import { useDashboardConfig, useAlertAnalysis } from '@/features/dashboard/hooks/useDashboard'
import { AnimatedContainer } from '@/components/animation/AnimationSystem'
import { ErrorBoundary } from '@/components/error/ErrorBoundary'

interface AppLayoutProps {
  children: ReactNode
  title?: string
  alertCount?: number
  fullWidth?: boolean // 新增：是否全宽显示
}

export const AppLayout: React.FC<AppLayoutProps> = ({
  children,
  title = "巡检系统",
  alertCount = 0,
  fullWidth = false
}) => {
  const pathname = usePathname()
  const { config, toggleSidebar } = useDashboardConfig()

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Sidebar */}
      <Sidebar
        isOpen={config.sidebarOpen}
        onToggle={toggleSidebar}
        currentPath={pathname}
      />

      {/* Main Content */}
      <div className={`${config.sidebarOpen ? 'ml-64' : 'ml-20'} transition-all duration-300`}>
        {/* Header */}
        <DashboardHeader
          alertCount={alertCount}
          title={title}
        />

        {/* Page Content */}
        <ErrorBoundary>
          <AnimatedContainer
            animation="pageTransition"
            className={fullWidth ? "p-2" : "p-6"}
          >
            {children}
          </AnimatedContainer>
        </ErrorBoundary>
      </div>
    </div>
  )
}

// Hook for using AppLayout with alert data
export const useAppLayout = () => {
  const { config, toggleSidebar } = useDashboardConfig()

  return {
    sidebarOpen: config.sidebarOpen,
    toggleSidebar
  }
}

import React, { useState } from 'react'
import Image from 'next/image'
import { motion, AnimatePresence } from 'framer-motion'
import { ImageIcon } from 'lucide-react'

interface OptimizedImageProps {
  src: string
  alt: string
  width?: number
  height?: number
  className?: string
  fill?: boolean
  priority?: boolean
  quality?: number
  blurDataURL?: string
  placeholder?: 'blur' | 'empty'
  sizes?: string
}

export const OptimizedImage: React.FC<OptimizedImageProps> = ({
  src,
  alt,
  width,
  height,
  className,
  fill,
  priority = false,
  quality = 75,
  blurDataURL,
  placeholder = 'empty',
  sizes = '(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw',
  ...props
}) => {
  const [isLoading, setIsLoading] = useState(true)
  const [hasError, setHasError] = useState(false)

  const handleLoad = () => {
    setIsLoading(false)
  }

  const handleError = () => {
    setIsLoading(false)
    setHasError(true)
  }

  // 生成默认的 blur data URL
  const defaultBlurDataURL = 'data:image/jpeg;base64,'

  if (hasError) {
    return (
      <div className={`flex items-center justify-center bg-gray-100 ${className}`}>
        <div className="text-center">
          <ImageIcon className="w-8 h-8 text-gray-400 mx-auto mb-2" />
          <p className="text-sm text-gray-500">图片加载失败</p>
        </div>
      </div>
    )
  }

  return (
    <div className={`relative overflow-hidden ${className}`}>
      <AnimatePresence>
        {isLoading && (
          <motion.div
            initial={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 bg-gray-100 flex items-center justify-center z-10"
          >
            <div className="animate-spin rounded-full h-6 w-6 border-2 border-gray-300 border-t-blue-600"></div>
          </motion.div>
        )}
      </AnimatePresence>

      <Image
        src={src}
        alt={alt}
        width={width}
        height={height}
        fill={fill}
        priority={priority}
        quality={quality}
        placeholder={placeholder}
        blurDataURL={blurDataURL || defaultBlurDataURL}
        sizes={sizes}
        onLoad={handleLoad}
        onError={handleError}
        className="object-cover"
        {...props}
      />
    </div>
  )
}

