  { key: 'ssh_username', label: 'SSH 用户名', required: false },
  { key: 'ssh_password', label: 'SSH 密码', required: false }
]

const DEVICE_TYPES: Array<{ value: DeviceType; label: string }> = [
  { value: 'switch', label: '交换机' },
  { value: 'router', label: '路由器' },
  { value: 'firewall', label: '防火墙' },
  { value: 'wireless_ap', label: '无线 AP' }
]

const HEADER_HINTS: Record<string, keyof DeviceImportData> = {
  name: 'name',
  '设备名称': 'name',
  ip: 'ip',
  'ip地址': 'ip',
  'ip 地址': 'ip',
  device_type: 'device_type',
  '设备类型': 'device_type',
  type: 'device_type',
  location: 'location',
  '位置': 'location',
  description: 'description',
  '描述': 'description',
  snmp: 'snmp_community',
  'snmp 团体字符串': 'snmp_community',
  snmp_community: 'snmp_community',
  'ssh 用户名': 'ssh_username',
  ssh_username: 'ssh_username',
  'ssh 密码': 'ssh_password',
  ssh_password: 'ssh_password'
}

const createEmptyDevice = (): DeviceImportData => ({
  name: '',
  ip: '',
  device_type: 'switch',
  location: '',
  description: '',
  snmp_community: '',
  ssh_username: '',
  ssh_password: ''
})

const normalizeDevice = (partial: Partial<DeviceImportData>): DeviceImportData => ({
  name: partial.name ?? '',
  ip: partial.ip ?? '',
  device_type: (partial.device_type as DeviceType | undefined) ?? 'switch',
  location: partial.location ?? '',
  description: partial.description ?? '',
  snmp_community: partial.snmp_community ?? '',
  ssh_username: partial.ssh_username ?? '',
  ssh_password: partial.ssh_password ?? ''
})

const detectField = (header: string): keyof DeviceImportData | '' => {
  const normalized = header.toLowerCase().replace(/\s+/g, '')
  const matchedEntry = Object.entries(HEADER_HINTS).find(([key]) =>
    normalized.includes(key.toLowerCase().replace(/\s+/g, ''))
  )
  return matchedEntry ? matchedEntry[1] : ''
}

export const BulkDeviceImport: React.FC<BulkDeviceImportProps> = ({ isOpen, onClose, onImport }) => {
  const [step, setStep] = useState<ImportStep>('upload')
  const [csvData, setCsvData] = useState<ParsedCSVData | null>(null)
  const [fieldMapping, setFieldMapping] = useState<Record<string, keyof DeviceImportData | ''>>({})
  const [isProcessing, setIsProcessing] = useState(false)
  const [importResult, setImportResult] = useState<ImportResult | null>(null)
  const [manualDevices, setManualDevices] = useState<DeviceImportData[]>([createEmptyDevice()])
  const [mappingErrors, setMappingErrors] = useState<string[]>([])

  const mappedDevices = useMemo(() => {
    if (!csvData) return []
    return csvData.rows.map(row => {
      const partial: Partial<DeviceImportData> = {}
      csvData.headers.forEach((header, index) => {
        const target = fieldMapping[header]
        if (target) {
          partial[target] = row[index]?.trim() ?? ''
        }
      })
      return normalizeDevice(partial)
    })
  }, [csvData, fieldMapping])

  const resetState = () => {
    setStep('upload')
    setCsvData(null)
    setFieldMapping({})
    setImportResult(null)
    setManualDevices([createEmptyDevice()])
    setMappingErrors([])
  }

  const handleClose = () => {
    if (isProcessing) return
    resetState()
    onClose()
  }

  const parseCSV = (content: string): ParsedCSVData => {
    const lines = content
      .split('\n')
      .map(line => line.replace(/\r$/, ''))
      .filter(line => line.trim().length > 0)

    if (lines.length <= 1) {
      throw new Error('CSV 内容为空或缺少数据行')
    }

    const headers = lines[0]
      .split(',')
      .map(cell => cell.trim().replace(/^"|"$/g, ''))

    const rows = lines.slice(1).map(line =>
      line.split(',').map(cell => cell.trim().replace(/^"|"$/g, ''))
    )

    return { headers, rows }
  }

  const handleFileUpload = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (!file) return

    const reader = new FileReader()
    reader.onload = e => {
      try {
        const content = (e.target?.result ?? '') as string
        const parsed = parseCSV(content)
        const defaultMapping: Record<string, keyof DeviceImportData | ''> = {}
        parsed.headers.forEach(header => {
          defaultMapping[header] = detectField(header)
        })
        setCsvData(parsed)
        setFieldMapping(defaultMapping)
        setMappingErrors([])
        setStep('mapping')
      } catch (error) {
        console.error('CSV 解析失败:', error)
      }
    }
    reader.readAsText(file, 'utf-8')
  }, [])

  const handleMappingConfirm = () => {
    const missing = FIELD_DEFINITIONS
      .filter(field => field.required)
      .filter(field => !Object.values(fieldMapping).includes(field.key))
      .map(field => field.label)

    if (missing.length > 0) {
      setMappingErrors(missing.map(label => `缺少必填字段映射：${label}`))
      return
    }

    setMappingErrors([])
    setStep('preview')
  }

  const handleManualDeviceChange = (index: number, field: keyof DeviceImportData, value: string) => {
    setManualDevices(prev => prev.map((device, idx) => (idx === index ? { ...device, [field]: value } : device)))
  }

  const addManualDevice = () => {
    setManualDevices(prev => [...prev, createEmptyDevice()])
  }

  const removeManualDevice = (index: number) => {
    setManualDevices(prev => (prev.length > 1 ? prev.filter((_, idx) => idx !== index) : prev))
  }

  const downloadTemplate = () => {
    const headerLine = '设备名称,IP地址,设备类型,位置,描述,SNMP团体字符串,SSH用户名,SSH密码'
    const sampleLines = [
      '核心交换机1,192.168.1.1,switch,数据中心A,核心网络设备,public,admin,',
      '路由器网关1,192.168.1.254,router,数据中心A,主网关路由器,public,admin,',
      '边界防火墙1,192.168.1.100,firewall,数据中心B,边界防护设备,public,admin,'
    ]
    const csvContent = [headerLine, ...sampleLines].join('\r\n')

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' })
    const link = document.createElement('a')
    link.href = URL.createObjectURL(blob)
    link.download = '设备导入模板.csv'
    link.click()
  }

  const handleImport = async () => {
    setIsProcessing(true)
    try {
      const devices = csvData ? mappedDevices : manualDevices.filter(device => device.name && device.ip)
      const result = await onImport(devices)
      setImportResult(result)
      setStep('result')
    } catch (error) {
      console.error('导入失败:', error)
    } finally {
      setIsProcessing(false)
    }
  }

  const renderUploadStep = () => (
    <div className="space-y-6">
      <div className="text-center">
        <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-blue-100 flex items-center justify-center">
          <Upload className="h-8 w-8 text-blue-600" />
        </div>
        <h3 className="text-lg font-semibold text-gray-900 mb-2">批量导入设备</h3>
        <p className="text-sm text-gray-600">支持上传 CSV 文件或手动添加设备。</p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="text-sm">CSV 文件导入</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <div className="flex items-center gap-3">
              <Button variant="outline" onClick={downloadTemplate} className="flex items-center gap-2">
                <Download className="h-4 w-4" />
                下载模板
              </Button>
              <span className="text-sm text-gray-500">下载模板后填写设备信息并重新上传。</span>
            </div>
            <label className="flex flex-col gap-3 border-2 border-dashed border-gray-300 rounded-lg p-6 text-center cursor-pointer hover:border-blue-400 transition-colors">
              <input type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
              <FileText className="h-10 w-10 mx-auto text-blue-500" />
              <div className="text-sm text-gray-600">点击上传或将文件拖拽到此区域，支持 CSV 格式</div>
            </label>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-sm">手动添加设备</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {manualDevices.map((device, index) => {
            const nameId = `manual-name-${index}`
            const ipId = `manual-ip-${index}`
            const locationId = `manual-location-${index}`
            const descriptionId = `manual-description-${index}`

            return (
              <div key={`${device.ip || 'device'}-${index}`} className="grid grid-cols-1 md:grid-cols-5 gap-3 items-end bg-gray-50 p-4 rounded-lg">
                <div className="flex flex-col gap-1">
                  <label className="text-xs font-medium text-gray-500" htmlFor={nameId}>
                    设备名称
                  </label>
                  <Input
                    id={nameId}
                    value={device.name}
                    onChange={event => handleManualDeviceChange(index, 'name', event.target.value)}
                  />
                </div>
                <div className="flex flex-col gap-1">
                  <label className="text-xs font-medium text-gray-500" htmlFor={ipId}>
                    IP 地址
                  </label>
                  <Input
                    id={ipId}
                    value={device.ip}
                    onChange={event => handleManualDeviceChange(index, 'ip', event.target.value)}
                  />
                </div>
                <div className="flex flex-col gap-1">
                  <label className="text-xs font-medium text-gray-500">设备类型</label>
                  <Select
                    value={device.device_type}
                    onValueChange={(value: DeviceType) => handleManualDeviceChange(index, 'device_type', value)}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="请选择设备类型" />
                    </SelectTrigger>
                    <SelectContent>
                      {DEVICE_TYPES.map(item => (
                        <SelectItem key={item.value} value={item.value}>
                          {item.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="flex flex-col gap-1">
                  <label className="text-xs font-medium text-gray-500" htmlFor={locationId}>
                    位置
                  </label>
                  <Input
                    id={locationId}
                    value={device.location ?? ''}
                    onChange={event => handleManualDeviceChange(index, 'location', event.target.value)}
                  />
                </div>
                <div className="flex items-end justify-end">
                  <Button
                    type="button"
                    variant="ghost"
                    onClick={() => removeManualDevice(index)}
                    disabled={manualDevices.length === 1}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
                <div className="md:col-span-5 flex flex-col gap-1">
                  <label className="text-xs font-medium text-gray-500" htmlFor={descriptionId}>
                    描述
                  </label>
                  <Input
                    id={descriptionId}
                    value={device.description ?? ''}
                    onChange={event => handleManualDeviceChange(index, 'description', event.target.value)}
                  />
                </div>
              </div>
            )
          })}
          <Button variant="outline" className="flex items-center gap-2" onClick={addManualDevice}>
            <Plus className="h-4 w-4" /> 添加设备
          </Button>
          <div className="text-right">
            <Button onClick={() => setStep('preview')}>
              下一步
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  )

  const renderMappingStep = () => (
    <div className="space-y-6">
      <h3 className="text-lg font-semibold text-gray-900">字段映射</h3>
      <p className="text-sm text-gray-600">请确认 CSV 列与系统字段的对应关系。</p>
      {mappingErrors.length > 0 && (
        <div className="bg-red-50 border border-red-200 text-red-700 text-sm rounded-lg p-4 space-y-1">
          {mappingErrors.map(errorMessage => (
            <div key={errorMessage} className="flex items-center gap-2">
              <AlertCircle className="h-4 w-4" />
              <span>{errorMessage}</span>
            </div>
          ))}
        </div>
      )}
      <div className="space-y-4">
        {csvData?.headers.map(header => (
          <div key={header} className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
            <div>
              <p className="text-sm font-medium text-gray-900">{header}</p>
              <p className="text-xs text-gray-500">来自 CSV 文件</p>
            </div>
            <div className="md:col-span-2">
              <Select
                value={fieldMapping[header] ?? ''}
                onValueChange={value =>
                  setFieldMapping(prev => ({ ...prev, [header]: value ? (value as keyof DeviceImportData) : '' }))
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="请选择对应字段" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">忽略该列</SelectItem>
                  {FIELD_DEFINITIONS.map(field => (
                    <SelectItem key={field.key} value={field.key}>
                      {field.label}
                      {field.required ? '（必填）' : ''}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        ))}
      </div>
      <div className="flex justify-end gap-3">
        <Button variant="outline" onClick={() => setStep('upload')} disabled={isProcessing}>
          上一步
        </Button>
        <Button onClick={handleMappingConfirm} disabled={isProcessing}>
          下一步
        </Button>
      </div>
    </div>
  )

  const renderPreviewStep = () => {
    const previewDevices = csvData ? mappedDevices : manualDevices
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-lg font-semibold text-gray-900">导入预览</h3>
            <p className="text-sm text-gray-600">共有 {previewDevices.length} 条记录将被导入。</p>
          </div>
          <Button variant="ghost" onClick={() => setStep(csvData ? 'mapping' : 'upload')} disabled={isProcessing}>
            返回修改
          </Button>
        </div>
        <div className="border border-gray-200 rounded-lg overflow-hidden">
          <div className="grid grid-cols-7 bg-gray-50 px-4 py-2 text-xs font-medium text-gray-500">
            <span>名称</span>
            <span>IP 地址</span>
            <span>类型</span>
            <span>位置</span>
            <span>描述</span>
            <span>SNMP 团体字符串</span>
            <span>SSH 用户名</span>
          </div>
          <div className="max-h-64 overflow-y-auto divide-y">
            {previewDevices.map((device, index) => (
              <div key={`${device.name || device.ip || 'device'}-${index}`} className="grid grid-cols-7 px-4 py-2 text-xs text-gray-700">
                <span>{device.name || '-'}</span>
                <span>{device.ip || '-'}</span>
                <span>{device.device_type}</span>
                <span>{device.location || '-'}</span>
                <span className="truncate" title={device.description ?? ''}>{device.description || '-'}</span>
                <span>{device.snmp_community || '-'}</span>
                <span>{device.ssh_username || '-'}</span>
              </div>
            ))}
          </div>
        </div>
        <div className="flex justify-end gap-3">
          <Button variant="outline" onClick={() => setStep(csvData ? 'mapping' : 'upload')} disabled={isProcessing}>
            上一步
          </Button>
          <Button
            onClick={handleImport}
            disabled={
              isProcessing ||
              (csvData ? mappedDevices.length === 0 : manualDevices.every(device => !device.name || !device.ip))
            }
          >
            {isProcessing ? <Loading size="sm" /> : '开始导入'}
          </Button>
        </div>
      </div>
    )
  }

  const renderResultStep = () => (
    <div className="space-y-6 text-center">
      <div className="w-16 h-16 mx-auto rounded-full bg-green-100 flex items-center justify-center">
        <CheckCircle className="h-10 w-10 text-green-600" />
      </div>
      <div>
        <h3 className="text-lg font-semibold text-gray-900">导入完成</h3>
        <p className="text-sm text-gray-600 mt-1">已导入 {importResult?.imported_count ?? 0} 条设备数据。</p>
      </div>
      {importResult && importResult.errors.length > 0 && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 text-left text-sm text-yellow-800">
          <h4 className="font-medium mb-2">以下记录导入失败：</h4>
          <ul className="space-y-1 list-disc list-inside">
            {importResult.errors.map((errorItem, index) => (
              <li key={`error-${errorItem.row}-${index}`}>
                第 {errorItem.row} 行 - {errorItem.error}
              </li>
            ))}
          </ul>
        </div>
      )}
      <div className="flex justify-center gap-3">
        <Button
          variant="outline"
          onClick={() => {
            setStep('upload')
            setCsvData(null)
          }}
        >
          继续导入
        </Button>
        <Button onClick={handleClose}>完成</Button>
      </div>
    </div>
  )

  return (
    <Modal
      open={isOpen}
      onOpenChange={open => {
        if (!open) {
          handleClose()
        }
      }}
    >
      <div className="p-6 space-y-6 max-w-4xl">
        {step === 'upload' && renderUploadStep()}
        {step === 'mapping' && renderMappingStep()}
        {step === 'preview' && renderPreviewStep()}
        {step === 'result' && renderResultStep()}
      </div>
    </Modal>
  )
}

import React, { useState } from 'react'
import { motion } from 'framer-motion'
import { 
  Play, 
  Square, 
  Clock, 
  CheckCircle, 
  XCircle, 
  AlertCircle,
  Eye,
  Download,
  RefreshCw,
  Calendar,
  User
} from 'lucide-react'
import {
  Card,
  CardHeader,
  CardTitle,
  CardContent,
  Button,
  Badge,
  Table,
  Column,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue
} from '@/components/atoms'
import { 
  useInspectionExecutions,
  useStopExecution,
  useGenerateReport
} from '../hooks/useInspection'
import { InspectionExecution } from '../types'

interface Props {
  searchText: string
}

export const InspectionExecutions: React.FC<Props> = ({ searchText }) => {
  const [statusFilter, setStatusFilter] = useState('all')
  const [selectedExecution, setSelectedExecution] = useState<InspectionExecution | null>(null)

  const { data: executionsData, isLoading, refetch } = useInspectionExecutions({
    status: statusFilter !== 'all' ? statusFilter : undefined
  })
  const stopExecution = useStopExecution()
  const generateReport = useGenerateReport()

  const executions: InspectionExecution[] = executionsData?.items || []

  // 过滤执行记录
  const filteredExecutions = executions.filter(execution => 
    execution.strategyName.toLowerCase().includes(searchText.toLowerCase())
  )

  const handleStopExecution = async (id: string) => {
    try {
      await stopExecution.mutateAsync(id)
    } catch (error) {
      console.error('Stop execution failed:', error)
    }
  }

  const handleGenerateReport = async (execution: InspectionExecution) => {
    try {
      await generateReport.mutateAsync({
        executionId: execution.id,
        type: 'summary',
        format: 'pdf'
      })
    } catch (error) {
      console.error('Generate report failed:', error)
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'running':
        return <RefreshCw className="w-4 h-4 text-blue-500 animate-spin" />
      case 'completed':
        return <CheckCircle className="w-4 h-4 text-green-500" />
      case 'failed':
        return <XCircle className="w-4 h-4 text-red-500" />
      case 'cancelled':
        return <Square className="w-4 h-4 text-gray-500" />
      default:
        return <Clock className="w-4 h-4 text-yellow-500" />
    }
  }

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'running':
        return <Badge variant="info">执行中</Badge>
      case 'completed':
        return <Badge variant="success">已完成</Badge>
      case 'failed':
        return <Badge variant="error">失败</Badge>
      case 'cancelled':
        return <Badge variant="secondary">已取消</Badge>
      default:
        return <Badge variant="warning">等待中</Badge>
    }
  }

  const getTriggerTypeBadge = (type: string) => {
    return type === 'scheduled' ? (
      <Badge variant="outline">定时触发</Badge>
    ) : (
      <Badge variant="secondary">手动触发</Badge>
    )
  }

  const formatDuration = (duration: number | undefined) => {
    if (!duration) return '-'
    const minutes = Math.floor(duration / 60)
    const seconds = duration % 60
    return `${minutes}分${seconds}秒`
  }

  const getScoreColor = (score: number) => {
    if (score >= 90) return 'text-green-600'
    if (score >= 70) return 'text-yellow-600'
    return 'text-red-600'
  }

  const columns: Column<InspectionExecution>[] = [
    {
      key: 'strategy',
      title: '策略信息',
      render: (execution) => (
        <div className="flex flex-col">
          <span className="font-medium text-gray-900">{execution.strategyName}</span>
          <div className="flex items-center gap-2 mt-1">
            {getTriggerTypeBadge(execution.triggerType)}
            {execution.triggerUser && (
              <div className="flex items-center gap-1 text-xs text-gray-500">
                <User className="w-3 h-3" />
                {execution.triggerUser}
              </div>
            )}
          </div>
        </div>
      )
    },
    {
      key: 'status',
      title: '执行状态',
      render: (execution) => (
        <div className="flex items-center gap-2">
          {getStatusIcon(execution.status)}
          {getStatusBadge(execution.status)}
        </div>
      )
    },
    {
      key: 'progress',
      title: '进度',
      render: (execution) => (
        <div className="flex flex-col">
          <div className="flex items-center gap-2">
            <div className="flex-1 bg-gray-200 rounded-full h-2">
              <div 
                className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                style={{ width: `${execution.progress}%` }}
              />
            </div>
            <span className="text-sm font-medium">{execution.progress}%</span>
          </div>
          <div className="text-xs text-gray-500 mt-1">
            {execution.completedDevices}/{execution.totalDevices} 设备
          </div>
        </div>
      )
    },
    {
      key: 'result',
      title: '巡检结果',
      render: (execution) => (
        <div className="flex flex-col">
          <div className={`text-lg font-bold ${getScoreColor(execution.summary.score)}`}>
            {execution.summary.score.toFixed(1)}
          </div>
          <div className="text-xs text-gray-500">
            通过: {execution.summary.passedChecks}/{execution.summary.totalChecks}
          </div>
        </div>
      )
    },
    {
      key: 'timing',
      title: '执行时间',
      render: (execution) => (
        <div className="flex flex-col text-sm">
          <div className="flex items-center gap-1">
            <Calendar className="w-3 h-3 text-gray-400" />
            {new Date(execution.startTime).toLocaleDateString()}
          </div>
          <div className="flex items-center gap-1 text-gray-500">
            <Clock className="w-3 h-3" />
            {new Date(execution.startTime).toLocaleTimeString()}
          </div>
          {execution.duration && (
            <div className="text-xs text-gray-500 mt-1">
              耗时: {formatDuration(execution.duration)}
            </div>
          )}
        </div>
      )
    },
    {
      key: 'actions',
      title: '操作',
      render: (execution) => (
        <div className="flex items-center gap-1">
          <Button
            size="sm"
            variant="ghost"
            onClick={() => setSelectedExecution(execution)}
            title="查看详情"
          >
            <Eye className="w-4 h-4" />
          </Button>
          {execution.status === 'running' && (
            <Button
              size="sm"
              variant="ghost"
              onClick={() => handleStopExecution(execution.id)}
              disabled={stopExecution.isPending}
              title="停止执行"
            >
              <Square className="w-4 h-4 text-red-500" />
            </Button>
          )}
          {execution.status === 'completed' && (
            <Button
              size="sm"
              variant="ghost"
              onClick={() => handleGenerateReport(execution)}
              disabled={generateReport.isPending}
              title="生成报告"
            >
              <Download className="w-4 h-4" />
            </Button>
          )}
        </div>
      )
    }
  ]

  if (isLoading) {
    return (
      <div className="space-y-4">
        {/* 加载骨架屏 */}
        {[...Array(5)].map((_, index) => (
          <Card key={index} className="animate-pulse">
            <CardContent className="p-4">
              <div className="flex items-center gap-4">
                <div className="h-4 bg-gray-200 rounded w-1/4"></div>
                <div className="h-4 bg-gray-200 rounded w-1/6"></div>
                <div className="h-4 bg-gray-200 rounded w-1/6"></div>
                <div className="h-4 bg-gray-200 rounded w-1/4"></div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {/* 操作栏 */}
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-2">
          <h3 className="text-lg font-semibold">执行历史记录</h3>
          <Badge variant="secondary">{filteredExecutions.length} 项</Badge>
        </div>
        <div className="flex gap-2">
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-32">
              <SelectValue placeholder="状态筛选" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">全部状态</SelectItem>
              <SelectItem value="running">执行中</SelectItem>
              <SelectItem value="completed">已完成</SelectItem>
              <SelectItem value="failed">失败</SelectItem>
              <SelectItem value="cancelled">已取消</SelectItem>
            </SelectContent>
          </Select>
          <Button variant="outline" onClick={() => refetch()}>
            <RefreshCw className="w-4 h-4 mr-2" />
            刷新
          </Button>
        </div>
      </div>

      {/* 执行统计 */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        {[
          { label: '总执行数', count: executions.length, color: 'blue' },
          { label: '执行中', count: executions.filter(e => e.status === 'running').length, color: 'blue' },
          { label: '已完成', count: executions.filter(e => e.status === 'completed').length, color: 'green' },
          { label: '失败', count: executions.filter(e => e.status === 'failed').length, color: 'red' },
          { label: '平均评分', count: executions.length > 0 ? 
            (executions.reduce((sum, e) => sum + e.summary.score, 0) / executions.length).toFixed(1) : '0', 
            color: 'purple' }
        ].map((item) => (
          <Card key={item.label}>
            <CardContent className="p-4 text-center">
              <div className={`text-2xl font-bold text-${item.color}-600`}>{item.count}</div>
              <div className="text-sm text-gray-600">{item.label}</div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* 执行记录列表 */}
      {filteredExecutions.length > 0 ? (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.3 }}
        >
          <Table
            data={filteredExecutions}
            columns={columns}
            className="bg-white rounded-lg shadow-sm"
          />
        </motion.div>
      ) : (
        <Card>
          <CardContent className="p-8 text-center">
            <div className="flex flex-col items-center gap-4">
              <AlertCircle className="w-12 h-12 text-gray-400" />
              <div>
                <h3 className="text-lg font-medium text-gray-900">暂无执行记录</h3>
                <p className="text-gray-500 mt-1">
                  {searchText ? '没有找到匹配的执行记录' : '还没有执行过巡检任务'}
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

