// 状态管理Hooks
type StrategyFilterType = 'all' | 'scheduled' | 'manual'
type TemplateCategoryFilter = 'all' | 'network' | 'system' | 'security' | 'custom'
type ExecutionStatusFilter = 'all' | 'pending' | 'running' | 'completed' | 'failed' | 'cancelled'

interface InspectionFilterState {
  strategyType: StrategyFilterType
  templateCategory: TemplateCategoryFilter
  executionStatus: ExecutionStatusFilter
  dateRange: {
    start: string
    end: string
  }
  searchText: string
}

const createInitialFilterState = (): InspectionFilterState => ({
  strategyType: 'all',
  templateCategory: 'all',
  executionStatus: 'all',
  dateRange: { start: '', end: '' },
  searchText: ''
})

export const useInspectionFilters = () => {
  const [filters, setFilters] = useState<InspectionFilterState>(() => createInitialFilterState())

  const updateFilter = useCallback(<K extends keyof InspectionFilterState>(key: K, value: InspectionFilterState[K]) => {
    setFilters(prev => ({
      ...prev,
      [key]: value
    }))
  }, [])

  const resetFilters = useCallback(() => {
    setFilters(createInitialFilterState())
  }, [])

  return {
    filters,
    updateFilter,
    resetFilters
  }
}

// 实时执行进度Hook - 暂时禁用，等待API实现
export const useExecutionProgress = (executionId: string, isRunning: boolean) => {
  const [progress] = useState({
    progress: 0,
    currentDevice: '',
    completedDevices: 0,
    totalDevices: 0,
    estimatedTimeRemaining: 0,
  })

  const { refetch } = useQuery({
    queryKey: ['inspection', 'execution', executionId, 'progress'],
    queryFn: () => Promise.resolve(progress),
    enabled: !!executionId && isRunning,
    refetchInterval: 1000, // 每秒更新
  })

  return {
    progress,
    refetchProgress: refetch,
  }
}

﻿import { api } from '@/lib/api-client'
import { NetworkStat, DeviceMonitoringStatus, NetworkTraffic, AlertSummary, MonitoringData } from '../types'

/**
 * 监控模块 API 接口
 * 已连接真实后端API - 支持实时数据更新
 */


interface NetworkStatApi {
  title?: string
  name?: string
  value: string
  change?: string
  trend?: 'up' | 'down' | string
  icon?: string
  color?: string
  data?: number[]
}

interface DeviceStatusApi {
  name: string
  status?: string
  cpu?: number
  cpu_usage?: number
  memory?: number
  memory_usage?: number
  uptime?: string
  last_seen?: string
  alerts?: number
  alert_count?: number
}

interface NetworkTrafficMetricApi {
  value?: string
  percentage?: number
  current?: number
  peak?: number
  data?: number[]
}

interface NetworkTrafficApi {
  inbound?: NetworkTrafficMetricApi
  outbound?: NetworkTrafficMetricApi
  packetLoss?: { value?: string; percentage?: number }
  peakTime?: string
}

interface AlertSummaryApi {
  critical?: number
  warning?: number
  info?: number
  recent?: Array<{ id: number; message: string; severity: string; time: string }>
  trends?: { up: number; down: number; stable: number }
}

interface MonitoringOverviewApi {
  last_updated?: string
  total_alerts?: number
}
// 获取监控概览数据
export async function fetchMonitoringOverview(): Promise<MonitoringData> {
  try {
    const [overview, networkStatsRaw, deviceStatusRaw, networkTrafficRaw, alertSummaryRaw] = await Promise.all([
      api.get<MonitoringOverviewApi>('/monitoring/overview'),
      api.get<NetworkStatApi[]>('/monitoring/network-stats'),
      api.get<DeviceStatusApi[]>('/monitoring/devices'),
      api.get<NetworkTrafficApi>('/monitoring/traffic?time_range=24h'),
      api.get<AlertSummaryApi>('/monitoring/alerts/summary'),
    ])

    const networkStats = transformNetworkStatsData(networkStatsRaw)
    const deviceStatus = transformDeviceStatusData(deviceStatusRaw)
    const networkTraffic = transformTrafficData(networkTrafficRaw)
    const alertSummary = transformAlertSummaryData(alertSummaryRaw)

    return {
      networkStats,
      deviceStatus,
      networkTraffic,
      alertSummary,
      lastUpdate: overview?.last_updated ?? new Date().toISOString(),
      totalAlerts:
        (alertSummary?.critical ?? 0) +
        (alertSummary?.warning ?? 0) +
        (alertSummary?.info ?? 0),
    }
