        )}
      </div>

      {Object.keys(summary.devices).length === 0 ? (
        <Card>
          <CardContent className="p-8 text-center text-gray-500">
            暂无设备流量数据
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-4">
          {Object.entries(summary.devices).map(([deviceIp, deviceData], index) => (
            <motion.div
              key={deviceIp}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 * (index + 1) }}
            >
              <Card className="hover:shadow-md transition-shadow">
                <CardHeader className="pb-3">
                  <div className="flex items-center justify-between">
                    <CardTitle className="text-base font-medium">
                      {deviceIp}
                    </CardTitle>
                    <Badge variant="outline">
                      {deviceData.interface_count} 接口
                    </Badge>
                  </div>
                </CardHeader>
                <CardContent className="space-y-4">
                  {/* 接口列表 */}
                  <div className="space-y-2">
                    <h4 className="text-sm font-medium text-gray-700">网络接口</h4>
                    <div className="space-y-2">
                      {Object.entries(deviceData.interfaces).map(([interfaceName, interfaceData]) => (
                        <div key={interfaceName} className="flex items-center justify-between p-2 bg-gray-50 rounded">
